// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;
    Recorder rec;

    function setUp() public {
        c = new SimpleWallet();
        rec = new Recorder();
    }

    function testFuzz_property(uint256 amount, bytes memory data) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(amount <= address(c).balance ? false : true);
        // fund the contract so the amount is admissible
        vm.deal(address(c), 0);
        vm.deal(address(this), amount);
        (bool okSelf, ) = address(c).call{value: amount}("");
        assertTrue(okSelf);
        // fund again via payable fallback
        if (amount > 0 && address(c).balance < amount) {
            vm.deal(address(c), amount);
        }

        uint256 recBefore = address(rec).balance;
        vm.prank(c.owner());
        c.sendMoney(address(rec), amount, data);

        // General rule: sendMoney must actually forward exactly `amount` wei
        // to the target, and the target must receive it.
        assertTrue(address(rec).balance == recBefore + amount && rec.lastValue() == amount);
    }

    receive() external payable {}
}

contract Recorder {
    uint256 public lastValue;
    uint256 public callCount;
    fallback() external payable {
        lastValue = msg.value;
        callCount++;
    }
    receive() external payable {
        lastValue = msg.value;
        callCount++;
    }
}
